async function fill(report){const m=await caches.open(MEDIA);let have=0;const todo=[];
  for(const f of MEDIA_FILES){if(await m.match(mk(f)))have++;else todo.push(f)}report(have);
  for(const f of todo){try{const r=await fetch(mk(f),{cache:"no-store"});if(r.ok){await m.put(mk(f),r);have++;if(have%10==0)report(have)}}catch(err){break}}report(have)}
